export { };
declare global {

    interface Window {

        craftale: {

            /*
            |--------------------------------------------------------------------------
            | APPLICATION
            |--------------------------------------------------------------------------
            */

            app: {

                name: string;

                version: string;

            };


            /*
            |--------------------------------------------------------------------------
            | FILESYSTEM
            |--------------------------------------------------------------------------
            */

            filesystem: {

                /*
                |--------------------------------------------------------------------------
                | Select Folder
                |--------------------------------------------------------------------------
                */

                selectFolder(): Promise<
                    string | null
                >;


                /*
                |--------------------------------------------------------------------------
                | Read Directory
                |--------------------------------------------------------------------------
                */

                readDirectory(
                    directoryPath: string
                ): Promise<{

                    name: string;

                    path: string;

                    type:
                    | "file"
                    | "directory";

                }[]>;


                /*
                |--------------------------------------------------------------------------
                | Read File
                |--------------------------------------------------------------------------
                */

                readFile(
                    filePath: string
                ): Promise<string>;


                /*
                |--------------------------------------------------------------------------
                | Write File
                |--------------------------------------------------------------------------
                */

                writeFile(
                    filePath: string,
                    content: string
                ): Promise<boolean>;

            };

        };

    };

}